static Map<Long, User> cache = new HashMap<>();
static Optional<User> findByIdCached(UserJdbcDao dao, long id) {
  Optional<User> cached = Optional.ofNullable(cache.get(id));
  if (cached.isPresent()) return cached;
  Optional<User> fromDb = dao.findById(id);
  fromDb.ifPresent(u -> cache.put(id, u));
  return fromDb;
}

